import re,pathlib,json
b=pathlib.Path(r'$b')
res={}
for p in sorted(b.rglob('*.md')):
    t=p.read_text(encoding='utf-8')
    m=re.match(r'^---\s*\n(.*?)\n---\s*\n',t,re.S)
    if not m: continue
    fm=dict()
    for line in m.group(1).splitlines():
        if ':' in line:
            k,_,v=line.partition(':'); fm[k.strip()]=v.strip().strip(chr(34)+chr(39))
    if fm.get('id'): res[fm['id']]={'title':fm.get('title'),'type':fm.get('type'),'domain':fm.get('domain'),'file':p.relative_to(b).as_posix()}
pathlib.Path(r'$out').write_text(json.dumps(res,ensure_ascii=False,indent=1),encoding='utf-8')
print('wrote',out,len(res))
""}
